(()=>{'use strict';
const app=document.getElementById('app');
const desktop=globalThis.classJourneyDesktop;let desktopInfo=null,nativeInstallerReady=null;
const APP_INFO=JSON.parse(document.getElementById('app-info').textContent);
const clone=v=>JSON.parse(JSON.stringify(v));
const escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>globalThis.crypto?.randomUUID?.()||'id-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2);
const svgPaths={computer:'M3 4h18v13H3zM8 21h8M12 17v4',pause:'M8 5v14M16 5v14',reset:'M3 10a9 9 0 1 1 2 8M3 4v6h6',route:'M5 19c0-4 14-2 14-7S5 11 5 5m0 0 0 4m0-4 4 0',plus:'M12 5v14M5 12h14',back:'m14 6-6 6 6 6',edit:'m16 3 5 5-12 12-6 1 1-6L16 3zM14 5l5 5',play:'m8 5 11 7-11 7V5z',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',copy:'M9 8h12v13H9zM4 16H3V3h13v1',trash:'M3 6h18M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7M14 10v7',download:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',upload:'M12 16V4m-5 5 5-5 5 5M4 17v4h16v-4',full:'M8 3H3v5M16 3h5v5M3 16v5h5M21 16v5h-5',close:'m6 6 12 12M6 18 18 6',settings:'M4 6h16M4 12h16M4 18h16M8 3v6M16 9v6M10 15v6',help:'M9 8a3 3 0 1 1 5 2c-2 1-2 2-2 3m0 4v.1M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',clock:'M12 7v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',folder:'M3 5h7l2 3h9v12H3V5z',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3 3-7z',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12zm13 0a3 3 0 1 1-6 0 3 3 0 0 1 6 0',save:'M4 3h14l3 3v15H3V3h1zm3 0v6h10V3M7 21v-8h10v8'};
const ico=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${svgPaths[name]||svgPaths.route}"/></svg>`;
const iconNames={idea:'Einstieg',puzzle:'Aufgabe',break:'Pause',notebook:'Arbeiten',talk:'Austausch',check:'Sicherung',health:'Gesundheit',hygiene:'Hygiene',care:'Pflege',mobility:'Mobilität',resources:'Ressourcen',rest:'Ruhe'};
let state=validateCollection(JSON.parse(document.getElementById('embedded-data').textContent)),db=null,screen='library',selectedId='',draft=null;
let groupMode='class',groupValue='',search='',weekdayFilter='',pan=0,lessonData=null,timer=null,saveTimer=null,saveState='Lokale Sicherung wird vorbereitet',saveWarn=false,activeDialog=null,editingActivity=null,installPrompt=null;
if(state.libraryId==='classjourney-starter-v1'){try{let localId=localStorage.getItem('classjourney-library-id');if(!localId){localId='library-'+uid();localStorage.setItem('classjourney-library-id',localId);}state.libraryId=localId;}catch{}}
const lessonClock=createLessonClock();
const byId=id=>document.getElementById(id);
const plan=()=>state.plans.find(p=>p.id===selectedId);
const bg=p=>state.assets.backgrounds[p?.backgroundId]||Object.values(state.assets.backgrounds)[0];
function art(a,extra=''){
  const custom=safeImage(a.image);let image=custom,index=ICONS[a.icon]??3;
  if(!image)image=index>=6?state.assets.fageAtlas:state.assets.atlas;
  const i=index%6,position=custom?'center':`${i%3*50}% ${Math.floor(i/3)*100}%`;
  return `<span class="art-icon ${custom?'custom ':''}${extra}" aria-hidden="true" style="background-image:url('${image}');background-position:${position}"></span>`;
}
function toast(message,error=false){document.querySelector('.toast')?.remove();const el=document.createElement('div');el.className='toast'+(error?' error':'');el.setAttribute('role','status');el.textContent=message;document.body.append(el);setTimeout(()=>el.remove(),5200);}
function updateSaveStatus(){document.querySelectorAll('.save-status').forEach(el=>{el.textContent=saveState;el.classList.toggle('warn',saveWarn);});}
function persist(){state.modifiedAt=Date.now();clearTimeout(saveTimer);saveState='Wird lokal gesichert …';updateSaveStatus();const nativeSave=desktop?desktop.saveCollection(clone(state)):null;if(nativeSave)nativeSave.catch(()=>{});saveTimer=setTimeout(async()=>{
  try{if(desktop)await nativeSave;else{if(!db)throw new Error();await new Promise((resolve,reject)=>{const tx=db.transaction('library','readwrite');tx.objectStore('library').put(clone(state),state.libraryId);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});}saveState='Auf diesem Gerät gesichert';saveWarn=false;}catch{saveState='Bitte als Datei sichern';saveWarn=true;}updateSaveStatus();
},250);}
function restoreSaved(cached){let changed=false;if(cached&&cached.modifiedAt>state.modifiedAt){const builtins=state.assets,builtinPlans=state.plans;state=validateCollection(cached);const migration=migrateStarterPlans(state.plans,builtinPlans);state.plans=migration.plans;changed=migration.changed;const artChanged=refreshBuiltinArt(state.assets,builtins,APP_INFO.previousArt);if(artChanged&&state.settings.backgroundOpacity===0.62)state.settings.backgroundOpacity=0.82;changed=changed||artChanged;}return changed;}
async function openStorage(){let changed=false,initialNative=false;try{
  if(desktop){desktopInfo=await desktop.info();const cached=await desktop.loadCollection();changed=restoreSaved(cached);initialNative=!cached;}
  else{db=await new Promise((resolve,reject)=>{const request=indexedDB.open('classjourney-classroomscreen',1);request.onupgradeneeded=()=>request.result.createObjectStore('library');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);request.onblocked=()=>reject(new Error('Speicher blockiert'));});
  const cached=await new Promise((resolve,reject)=>{const r=db.transaction('library').objectStore('library').get(state.libraryId);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});changed=restoreSaved(cached);}
  saveState='Auf diesem Gerät gesichert';saveWarn=false;
}catch{saveState='Bitte als Datei sichern';saveWarn=true;}render();if(changed||initialNative)persist();}
function header(){return `<header class="topbar"><div class="row"><div class="brand"><span class="brand-mark">${ico('route')}</span>ClassJourney</div><span class="save-status ${saveWarn?'warn':''}" title="Deine Daten bleiben auf diesem Gerät">${escape(saveState)}</span></div><nav class="top-actions" aria-label="Werkzeuge"><span class="agent-tools" role="group" aria-label="Lokaler KI-Agent"><button class="agent-connect" data-action="connect-agent">${ico('spark')}<span>KI-Agent verbinden</span></button><button class="agent-help" data-action="agent-help" aria-label="KI-Verbindung erklären" title="Was passiert beim Verbinden?">?</button></span><button class="icon-button" data-action="import" title="Sammlung importieren" aria-label="Sammlung laden">${ico('upload')}</button><button class="icon-button" data-action="export" title="Exportieren & teilen" aria-label="Speichern & teilen">${ico('download')}</button>${location.protocol!=='file:'?`<button class="icon-button" data-action="download-program" title="Für Windows & Mac herunterladen" aria-label="Für Windows & Mac herunterladen">${ico('computer')}</button>`:''}<span class="toolbar-divider"></span><button class="icon-button" data-action="updates" title="Updates" aria-label="Updates">${ico('route')}</button><button class="icon-button" data-action="install" id="install-button" title="App installieren" aria-label="Installieren" ${installPrompt?'':'hidden'}>${ico('plus')}</button><button class="icon-button" data-action="help" title="Hilfe & KI-Zugriff" aria-label="Hilfe">${ico('help')}</button></nav></header>`;}
function stopLesson(){if(timer)clearInterval(timer);timer=null;}
function render(){stopLesson();if(screen==='library')renderLibrary();else if(screen==='editor')renderEditor();else renderLesson();window.scrollTo(0,0);}
function planDay(p){return p.date?new Intl.DateTimeFormat('de-CH',{weekday:'long',day:'numeric',month:'long'}).format(new Date(p.date+'T12:00:00')):DAYS[p.weekday];}
function renderLibrary(){
  const groups=[...new Set(state.plans.map(p=>groupMode==='class'?p.className:p.topic))].sort((a,b)=>a.localeCompare(b,'de'));
  const filtered=state.plans.filter(p=>(!groupValue||(groupMode==='class'?p.className:p.topic)===groupValue)&&(!weekdayFilter||String(p.weekday)===weekdayFilter)&&(!search||`${p.title} ${p.className} ${p.topic} ${planDay(p)}`.toLowerCase().includes(search.toLowerCase()))).sort((a,b)=>a.className.localeCompare(b.className,'de')||((a.weekday+6)%7)-((b.weekday+6)%7)||a.title.localeCompare(b.title,'de'));
  const defaultBg=state.assets.backgrounds.journey||Object.values(state.assets.backgrounds)[0];
  app.innerHTML=`<div class="library">${header()}<main class="library-main"><section class="library-hero"><div class="hero-copy"><div class="eyebrow">Planbibliothek</div><h1>Unterrichtspläne</h1><p>Deine Klassen. Deine Themen. Dein nächster Unterrichtstag.</p></div></section><div class="library-layout"><aside class="side-nav" aria-label="Pläne ordnen"><div class="tabs"><button data-action="group-mode" data-value="class" class="${groupMode==='class'?'selected':''}">Klassen</button><button data-action="group-mode" data-value="topic" class="${groupMode==='topic'?'selected':''}">Themen</button></div><button class="side-item ${!groupValue?'selected':''}" data-action="group" data-value="">Alle Unterrichtstage<span class="count">${state.plans.length}</span></button><div class="side-caption">${groupMode==='class'?'Deine Klassen':'Themenblöcke'}</div>${groups.map(g=>`<button class="side-item ${g===groupValue?'selected':''}" data-action="group" data-value="${escape(g)}">${escape(g)}<span class="count">${state.plans.filter(p=>(groupMode==='class'?p.className:p.topic)===g).length}</span></button>`).join('')}<div class="side-note">Deine Pläne und Bilder bleiben in diesem Browser. Sichere deine Sammlung als Datei, um sie weiterzugeben oder auf einem anderen Gerät zu öffnen.</div></aside><section><div class="toolbar"><input id="plan-search" type="search" placeholder="Plan, Klasse oder Thema suchen …" aria-label="Pläne suchen" value="${escape(search)}"><select id="weekday-filter" aria-label="Nach Wochentag filtern"><option value="">Alle Wochentage</option>${[1,2,3,4,5,6,0].map(d=>`<option value="${d}" ${weekdayFilter===String(d)?'selected':''}>${DAYS[d]}</option>`).join('')}</select><button class="primary" data-action="new" title="Neuen Unterrichtstag erstellen">${ico('plus')}Neuer Plan</button></div>${state.plans.some(p=>p.isDemo)?'<div class="notice">Der Demo-Tag nutzt eine eigene Uhr. Neue und duplizierte Unterrichtstage folgen der Gerätezeit.</div>':''}<div class="results-count">${filtered.length} ${filtered.length===1?'Unterrichtstag':'Unterrichtstage'}${groupValue?' · '+escape(groupValue):''}</div><div class="plan-grid">${filtered.length?filtered.map(planCard).join(''):`<div class="empty"><h2>Hier beginnt dein nächster Tag.</h2><p>Erstelle einen Plan oder lade eine vorbereitete Sammlung.</p><button class="primary" data-action="new">${ico('plus')}Unterrichtstag erstellen</button></div>`}</div></section></div></main></div>`;
  byId('plan-search').addEventListener('input',e=>{search=e.target.value;const caret=e.target.selectionStart;renderLibrary();byId('plan-search').focus();byId('plan-search').setSelectionRange(caret,caret);});
  byId('weekday-filter').addEventListener('change',e=>{weekdayFilter=e.target.value;renderLibrary();});
}
function planCard(p){const s=schedule(p);return `<article class="plan-card"><div class="plan-image" style="background-image:url('${bg(p)?.src||''}')"><div class="plan-badges"><span class="tag">${escape(p.className)}</span><span class="tag">${escape(planDay(p))}</span>${p.isDemo?'<span class="tag">Demo · eigene Uhr</span>':''}</div></div><div class="plan-body"><div class="eyebrow">${escape(p.topic)}</div><h3>${escape(p.title)}</h3><div class="plan-meta">${ico('clock')}${timeLabel(s.start)}–${timeLabel(s.end)}<span>·</span>${p.activities.length} Aufträge</div><div style="margin-top:11px"><span class="tag ${s.overflow?'red':''}">${s.overflow?`${s.overflow} min passen nicht mehr hinein`:`${s.planned} von ${s.available} min geplant`}</span></div><div class="plan-bottom"><div class="row plan-open"><button class="primary icon-button small" data-action="open" data-id="${p.id}" title="Unterricht starten" aria-label="${escape(p.title)} öffnen">${ico('play')}</button>${p.isDemo?'':`<button class="icon-button small" data-action="preview" data-id="${p.id}" title="Vorschau" aria-label="${escape(p.title)} Vorschau">${ico('eye')}</button>`}</div><div class="plan-menu"><button class="icon-button small" data-action="edit-plan" data-id="${p.id}" aria-label="${escape(p.title)} bearbeiten">${ico('edit')}</button><button class="icon-button small" data-action="duplicate" data-id="${p.id}" aria-label="${escape(p.title)} duplizieren">${ico('copy')}</button><button class="icon-button small" data-action="delete-plan" data-id="${p.id}" aria-label="${escape(p.title)} löschen">${ico('trash')}</button></div></div></div></article>`;}
function createDraft(id){draft=id?clone(state.plans.find(p=>p.id===id)):{id:uid(),title:'Neuer Unterrichtstag',className:groupMode==='class'&&groupValue?groupValue:'Meine Klasse',topic:groupMode==='topic'&&groupValue?groupValue:'Allgemein',weekday:weekdayFilter?Number(weekdayFilter):2,date:'',slots:defaultLessonSlots([1,2]),activities:[],backgroundId:'journey',example:false,isDemo:false,updatedAt:Date.now()};screen='editor';render();}
function standardLesson(slot){return DEFAULT_LESSONS.find(l=>l.start===slot.start&&l.end===slot.end);}
function lessonLabel(slot,index){const l=standardLesson(slot);return l?'Lektion '+l.number:'Zeitfenster '+(index+1);}
function renderLessonPresets(){return `<div class="lesson-presets" aria-label="Standardlektionen auswählen">${DEFAULT_LESSONS.map(l=>{const selected=draft.slots.some(s=>s.start===l.start&&s.end===l.end);return `<button class="lesson-preset ${selected?'selected':''}" data-action="toggle-lesson" data-value="${l.number}" aria-pressed="${selected}" aria-label="Lektion ${l.number}: ${l.start}–${l.end}${l.marker||''}" title="Lektion ${l.number} · ${l.start}–${l.end}${l.marker||''}">${l.number}${l.marker||''}</button>`;}).join('')}</div><p class="section-note" style="margin:0 0 12px">Standardraster · Lektionen für diesen Tag auswählen.</p>`;}
function renderEditor(){
  app.innerHTML=`${header()}<main class="editor"><div class="editor-heading"><div><div class="eyebrow">Unterricht vorbereiten</div><h1 style="margin-top:8px">${escape(draft.title)}</h1></div><div class="row"><button data-action="cancel-editor">Abbrechen</button><button class="primary" data-action="save-plan">${ico('save')}Plan speichern</button></div></div>${draft.isDemo?'<div class="notice">Du bearbeitest den Demo-Tag mit eigener Uhr. Für deinen Unterricht kannst du ihn in der Planbibliothek duplizieren.</div>':''}<div id="editor-error" class="form-error" role="alert"></div><div class="editor-layout"><div><section class="panel"><h2>Dein Unterrichtstag</h2><div class="field-grid"><label class="span2">Titel<input data-field="title" value="${escape(draft.title)}" maxlength="180"></label><label>Klasse<input data-field="className" value="${escape(draft.className)}" maxlength="80" placeholder="z. B. 1i" list="known-classes"></label><label>Themenblock<input data-field="topic" value="${escape(draft.topic)}" maxlength="140" placeholder="z. B. E2 Ressourcen" list="known-topics"></label><label>Wochentag<select data-field="weekday" ${draft.date?'disabled':''}>${[1,2,3,4,5,6,0].map(d=>`<option value="${d}" ${draft.weekday===d?'selected':''}>${DAYS[d]}</option>`).join('')}</select></label><label>Datum <span class="muted" style="font-weight:400">optional</span><input type="date" data-field="date" value="${draft.date}"></label></div><datalist id="known-classes">${[...new Set(state.plans.map(p=>p.className))].map(c=>`<option value="${escape(c)}">`).join('')}</datalist><datalist id="known-topics">${[...new Set(state.plans.map(p=>p.topic))].map(c=>`<option value="${escape(c)}">`).join('')}</datalist></section><section class="panel"><div class="row between" style="margin-bottom:18px"><h2 style="margin:0">Unterrichtszeiten</h2><button class="small" data-action="add-slot">${ico('plus')}Lektion</button></div>${renderLessonPresets()}${draft.slots.map((s,i)=>`<div class="slot-row"><span class="slot-lesson-number" title="${lessonLabel(s,i)}">${standardLesson(s)?.number||"–"}${standardLesson(s)?.marker||""}</span><input type="time" aria-label="${lessonLabel(s,i)} Beginn" data-slot="${i}" data-edge="start" value="${s.start}"><span>–</span><input type="time" aria-label="${lessonLabel(s,i)} Ende" data-slot="${i}" data-edge="end" value="${s.end}"><button class="icon-button small ghost" data-action="remove-slot" data-index="${i}" aria-label="${lessonLabel(s,i)} entfernen" ${draft.slots.length===1?'disabled':''}>${ico('close')}</button></div>`).join('')}${state.plans.filter(p=>p.id!==draft.id).length?`<select id="copy-slots" aria-label="Unterrichtszeiten übernehmen" style="width:100%;margin-top:9px"><option value="">Zeiten aus einem anderen Plan übernehmen …</option>${state.plans.filter(p=>p.id!==draft.id).map(p=>`<option value="${p.id}">${escape(p.className)} · ${escape(planDay(p))} · ${escape(p.title)}</option>`).join('')}</select>`:''}<p class="section-note">Lücken zwischen Lektionen bleiben feste Pausen. Arbeitsaufträge laufen danach weiter. Eine kurze Pause innerhalb einer Lektion kannst du als eigenen Auftrag einfügen.</p></section><section class="panel"><div class="row between" style="margin-bottom:16px"><h2 style="margin:0">Dein Hintergrund</h2><button class="small" data-action="upload-bg">${ico('upload')}Eigenes Bild</button></div><div class="bg-grid">${Object.entries(state.assets.backgrounds).map(([id,b])=>`<button class="bg-option ${id===draft.backgroundId?'selected':''}" data-action="choose-bg" data-id="${id}" style="background-image:url('${b.src}')" aria-label="Hintergrund ${escape(b.name)} wählen"><span>${escape(b.name)}</span></button>`).join('')}</div><p class="section-note">Der Skill «Class Journey» ergänzt thematisch passende Reisehintergründe und Symbole aus deinen Unterrichtsunterlagen.</p></section></div><section class="panel"><div class="row between" style="margin-bottom:18px"><h2 style="margin:0">Aufträge & Ablauf</h2><button class="small" data-action="add-activity">${ico('plus')}Auftrag</button></div><div id="editor-schedule"></div><button class="soft" data-action="add-activity" style="width:100%;margin-top:16px">${ico('plus')}Weiteren Auftrag hinzufügen</button></section></div></main>`;
  app.querySelectorAll('[data-field]').forEach(el=>el.addEventListener('input',()=>{const f=el.dataset.field;draft[f]=f==='weekday'?Number(el.value):el.value;if(f==='date'){if(draft.date)draft.weekday=new Date(draft.date+'T12:00:00').getDay();const field=app.querySelector('[data-field=weekday]');field.value=draft.weekday;field.disabled=!!draft.date;}}));
  app.querySelectorAll('[data-slot]').forEach(el=>el.addEventListener('change',()=>{draft.slots[Number(el.dataset.slot)][el.dataset.edge]=el.value;renderEditorSchedule();}));
  byId('copy-slots')?.addEventListener('change',e=>{const p=state.plans.find(p=>p.id===e.target.value);if(p){draft.slots=clone(p.slots);renderEditor();}});
  renderEditorSchedule();
}
function renderEditorSchedule(){try{const s=schedule(draft);byId('editor-schedule').innerHTML=`<div class="schedule-summary"><span class="tag">${s.available} min verfügbar</span><span class="tag">${s.planned} min geplant</span>${s.overflow?`<span class="tag red">${s.overflow} min ausserhalb</span>`:`<span class="tag">${s.available-s.planned} min frei</span>`}</div>${s.overflow?'<div class="notice error">Die roten Aufträge passen ganz oder teilweise nicht mehr hinein. Du kannst sie selbst kürzen.</div>':''}<div class="activity-list">${s.activities.map((a,i)=>`<article class="activity-row ${a.overflow?'overflow':''}">${art(a.activity)}<div><h3><span class="editable-title" contenteditable="plaintext-only" role="textbox" data-title="${a.activity.id}" aria-label="Titel ${escape(a.activity.title)}">${escape(a.activity.title)}</span></h3><small>${timeLabel(a.start)}–${timeLabel(a.end)}${a.segments.filter(s=>!s.overflow).length>1?' · über eine Lektionspause hinweg':''}${a.overflow?' · '+a.overflow+' min ausserhalb':''}</small></div><div class="activity-actions"><div class="duration-controls"><button class="small icon-button" data-action="duration" data-id="${a.activity.id}" data-delta="-5" aria-label="${escape(a.activity.title)} um fünf Minuten kürzen">−</button><input class="duration-input" type="number" min="1" max="1440" step="1" data-duration="${a.activity.id}" value="${a.activity.duration}" aria-label="Dauer ${escape(a.activity.title)} in Minuten"><span class="duration-unit">min</span><button class="small icon-button" data-action="duration" data-id="${a.activity.id}" data-delta="5" aria-label="${escape(a.activity.title)} um fünf Minuten verlängern">+</button></div><button class="small icon-button ghost" data-action="edit-activity" data-id="${a.activity.id}" aria-label="${escape(a.activity.title)} bearbeiten">${ico('edit')}</button><div class="activity-order"><button class="ghost" data-action="move-activity" data-id="${a.activity.id}" data-delta="-1" aria-label="Auftrag nach oben" ${i===0?'disabled':''}>↑</button><button class="ghost" data-action="move-activity" data-id="${a.activity.id}" data-delta="1" aria-label="Auftrag nach unten" ${i===s.activities.length-1?'disabled':''}>↓</button></div><button class="small icon-button ghost" data-action="delete-activity" data-id="${a.activity.id}" aria-label="${escape(a.activity.title)} löschen">${ico('trash')}</button></div></article>`).join('')||'<div class="empty" style="padding:40px 15px"><p>Noch keine Aufträge. Ergänze einen Einstieg, Arbeitsphasen und eine Sicherung.</p></div>'}</div>`;byId('editor-error').textContent='';byId('editor-schedule').querySelectorAll('[data-duration]').forEach(el=>el.addEventListener('change',()=>{const a=draft.activities.find(a=>a.id===el.dataset.duration);const n=Number(el.value);if(Number.isInteger(n)&&n>=1&&n<=1440){a.duration=n;renderEditorSchedule();}else{el.value=a.duration;toast('Bitte eine ganze Zahl zwischen 1 und 1440 eingeben.',true);}}));byId('editor-schedule').querySelectorAll('[data-title]').forEach(el=>el.addEventListener('blur',()=>{const a=draft.activities.find(a=>a.id===el.dataset.title);a.title=el.textContent.trim().slice(0,180)||'Auftrag';el.textContent=a.title;}));}catch(e){byId('editor-schedule').innerHTML='';byId('editor-error').textContent=e.message;}}
function savePlan(){try{draft.title=draft.title.trim()||'Unterrichtstag';draft.className=draft.className.trim()||'Meine Klasse';draft.topic=draft.topic.trim()||'Allgemein';draft.updatedAt=Date.now();schedule(draft);const safe=validateCollection({...state,plans:[draft]}).plans[0];const at=state.plans.findIndex(p=>p.id===safe.id);if(at>=0)state.plans[at]=safe;else state.plans.push(safe);persist();screen='library';groupValue='';search='';weekdayFilter='';render();toast('Dein Unterrichtstag ist gespeichert.');}catch(e){byId('editor-error').textContent=e.message;}}
function showDialog(title,body,footer='',width=590){closeDialog();const dialog=document.createElement('dialog');dialog.style.width=width+'px';dialog.innerHTML=`<div class="dialog-head"><h2>${escape(title)}</h2><button class="icon-button ghost" data-action="close-dialog" aria-label="Schliessen">${ico('close')}</button></div><div class="dialog-body">${body}</div>${footer?`<div class="dialog-foot">${footer}</div>`:''}`;app.append(dialog);activeDialog=dialog;dialog.addEventListener('click',e=>{if(e.target===dialog){const rect=dialog.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)closeDialog();}});dialog.addEventListener('close',()=>{dialog.remove();if(activeDialog===dialog)activeDialog=null;});dialog.showModal();return dialog;}
function closeDialog(){if(activeDialog){const d=activeDialog;activeDialog=null;d.close();d.remove();}}
function openActivity(id){const target=screen==='editor'?draft:plan();editingActivity=id?clone(target.activities.find(a=>a.id===id)):{id:uid(),title:'Neuer Auftrag',description:'',duration:15,icon:'notebook',image:''};showDialog(id?'Auftrag bearbeiten':'Auftrag hinzufügen',`<div id="activity-error" class="form-error" role="alert"></div><div class="stack"><label>Titel<input id="activity-title" maxlength="180" value="${escape(editingActivity.title)}"></label><label>Kurzer Auftrag<textarea id="activity-description" maxlength="2000">${escape(editingActivity.description)}</textarea></label><label>Dauer in Minuten<input id="activity-duration" type="number" min="1" max="1440" step="1" value="${editingActivity.duration}"></label><div><div class="row between" style="margin-bottom:12px"><label>Symbol wählen</label><button class="small" data-action="upload-icon">${ico('upload')}Eigenes Bild</button></div><div class="icon-grid">${Object.keys(ICONS).map(k=>`<button class="symbol-option ${k===editingActivity.icon&&!editingActivity.image?'selected':''}" data-action="choose-icon" data-value="${k}">${art({icon:k})}<span>${iconNames[k]}</span></button>`).join('')}</div><div id="custom-icon-preview" style="margin-top:10px">${editingActivity.image?art(editingActivity):''}</div></div></div>`,`<button data-action="close-dialog">Abbrechen</button><button class="primary" data-action="save-activity">Übernehmen</button>`);byId('activity-title').focus();byId('activity-title').select();}
function saveActivity(){const duration=Number(byId('activity-duration').value);if(!Number.isInteger(duration)||duration<1||duration>1440){byId('activity-error').textContent='Bitte eine Dauer zwischen 1 und 1440 Minuten eingeben.';return;}editingActivity.title=byId('activity-title').value.trim()||'Auftrag';editingActivity.description=byId('activity-description').value;editingActivity.duration=duration;const target=screen==='editor'?draft:plan(),at=target.activities.findIndex(a=>a.id===editingActivity.id);if(at<0)target.activities.push(editingActivity);else target.activities[at]=editingActivity;target.updatedAt=Date.now();closeDialog();if(screen==='editor')renderEditorSchedule();else{persist();renderLesson();}}
function nowMinutes(){return lessonClock.now();}
function openLesson(id,preview=false){selectedId=id;lessonClock.open(plan(),preview);pan=0;screen='lesson';render();}
function renderClockControls(){
  const demo=lessonClock.mode==='demo';
  if(lessonClock.mode==='live')return `<button data-action="enable-preview">${ico('eye')}Vorschau</button>`;
  return `<strong title="${demo?'Unabhängig von der Gerätezeit':'Frei einstellbare Vorschauzeit'}">${demo?'Demo':'Vorschau'}</strong><input id="preview-time" aria-label="${demo?'Demo-Uhrzeit':'Vorschauzeit'}" type="time" value="${timeLabel(nowMinutes()).slice(0,5)}"><button data-action="preview-step" data-delta="-5" aria-label="Fünf Minuten zurück">−5</button><button data-action="preview-step" data-delta="5" aria-label="Fünf Minuten vor">+5</button>${demo?`<button class="icon-button" data-action="demo-toggle" title="${lessonClock.running?'Demo pausieren':'Demo fortsetzen'}" aria-label="${lessonClock.running?'Demo pausieren':'Demo fortsetzen'}">${ico(lessonClock.running?'pause':'play')}</button><button class="icon-button" data-action="demo-reset" title="Demo neu starten" aria-label="Demo neu starten">${ico('reset')}</button>`:'<button data-action="live">Echtzeit</button>'}`;
}
function renderLesson(){stopLesson();const p=plan();if(!p){screen='library';render();return;}lessonData=schedule(p);const today=new Date();const dateToday=`${today.getFullYear()}-${String(today.getMonth()+1).padStart(2,'0')}-${String(today.getDate()).padStart(2,'0')}`;app.innerHTML=`<main class="lesson" style="--bg-opacity:${state.settings.backgroundOpacity}"><div class="lesson-bg" style="background-image:url('${bg(p)?.src||''}')"></div><header class="lesson-header"><div class="lesson-title"><div class="eyebrow">${escape(p.className)} · ${escape(p.topic)}</div><h1>${escape(p.title)}</h1><p>${escape(planDay(p))} · ${timeLabel(lessonData.start)}–${timeLabel(lessonData.end)}</p>${p.date&&p.date!==dateToday?'<span class="lesson-date-badge">Plan für '+escape(planDay(p))+'</span>':''}</div><nav class="lesson-actions" aria-label="Unterricht"><button data-action="library">${ico('grid')}Pläne</button><button data-action="lesson-edit">${ico('edit')}Bearbeiten</button><button data-action="settings">${ico('settings')}Ansicht</button><button data-action="fullscreen">${ico('full')}Vollbild</button></nav></header><div class="lesson-clock"><div class="eyebrow" id="clock-label">${lessonClock.mode==='demo'?'Demo-Uhr':lessonClock.mode==='preview'?'Vorschauzeit':'Aktuelle Zeit'}</div><div class="clock-time" id="live-clock"></div><div class="clock-date" id="live-date"></div></div><aside class="lesson-countdown"><div class="eyebrow" id="current-label">Aktueller Auftrag</div><div class="countdown-number" id="countdown"></div><div class="countdown-title" id="countdown-title"></div><div class="progress"><div id="lesson-progress"></div></div></aside><div class="now-line" id="now-line"><div class="now-label">JETZT<span id="now-time"></span></div></div><section class="journey-viewport" id="journey-viewport" aria-label="Unterrichtsablauf"><div class="journey-stream" id="journey-stream" style="height:${lessonData.totalHeight}px">${lessonData.segments.map((s,i)=>journeyCard(s,i)).join('')}</div></section><div id="finished-slot"></div><button class="return-now" data-action="return-now" hidden>${ico('route')}Zurück zu Jetzt</button><div class="lesson-note">Der Ablauf bewegt sich langsam nach oben.</div><div class="preview-bar" id="preview-controls">${renderClockControls()}</div><footer class="lesson-bottom"><div class="overview-label">Tagesübersicht</div><div class="overview-track">${lessonData.activities.map(a=>`<button class="overview-item ${a.overflow?'overflow':''}" data-action="pan-activity" data-id="${a.activity.id}" id="overview-${a.activity.id}">${escape(a.activity.title)}<small>${timeLabel(a.start)}–${timeLabel(a.end)}${a.overflow?' · ausserhalb':''}</small></button>`).join('')||'<span class="muted">Ergänze zuerst Aufträge in deinem Plan.</span>'}</div></footer></main>`;
  byId('journey-viewport').addEventListener('wheel',e=>{e.preventDefault();pan=Math.max(-lessonData.totalHeight,Math.min(lessonData.totalHeight,pan-e.deltaY));updateLesson();},{passive:false});
  let touchY=null;byId('journey-viewport').addEventListener('touchstart',e=>{touchY=e.touches[0].clientY;},{passive:true});byId('journey-viewport').addEventListener('touchmove',e=>{if(touchY!==null){pan+=e.touches[0].clientY-touchY;touchY=e.touches[0].clientY;updateLesson();}},{passive:true});
  byId('preview-time')?.addEventListener('change',e=>{if(e.target.value){lessonClock.set(minutes(e.target.value));pan=0;updateLesson();}});updateLesson();timer=setInterval(updateLesson,1000);
}
function journeyCard(s,index){const a=s.activity,entry=lessonData.activities.find(e=>e.activity.id===s.activityId),continued=entry&&entry.segments[0].id!==s.id;return `<article class="journey-card ${s.overflow?'overflow':''} ${s.kind==='fixed-break'?'fixed-break':''}" id="segment-${s.id}" data-icon="${a.icon||"notebook"}" style="top:${s.y}px;height:${s.height}px">${art(a)}<div style="min-width:0"><h2>${escape(a.title)}${continued?'<span style="font-size:12px;font-weight:400;display:block;margin-top:4px">Fortsetzung</span>':''}</h2>${a.description?`<p class="description">${escape(a.description)}</p>`:''}<div class="card-meta"><span>${timeLabel(s.start)}–${timeLabel(s.end)}</span><span>${s.duration} min${entry&&entry.segments.length>1?' · '+a.duration+' min gesamt':''}</span></div>${s.overflow?'<div class="overflow-note">Ausserhalb der Unterrichtszeit</div>':''}</div><span class="phase-number">${String(index+1).padStart(2,'0')}</span>${s.activityId?`<button class="card-edit" data-action="edit-activity" data-id="${s.activityId}" aria-label="${escape(a.title)} bearbeiten">${ico('edit')}</button>`:''}</article>`;}
function updateLesson(){if(screen!=='lesson'||!byId('journey-stream'))return;const raw=nowMinutes(),now=state.settings.motion?raw:Math.floor(raw),data=lessonData,current=atTime(data,raw),n=new Date();byId('live-clock').textContent=timeLabel(raw);byId('live-date').textContent=lessonClock.mode==='demo'?'Unabhängig von der Gerätezeit':lessonClock.mode==='preview'?planDay(plan()):new Intl.DateTimeFormat('de-CH',{weekday:'long',day:'numeric',month:'long'}).format(n);if(lessonClock.mode==='demo'&&document.activeElement!==byId('preview-time'))byId('preview-time').value=timeLabel(raw).slice(0,5);byId('now-time').textContent=timeLabel(raw);const view=byId('journey-viewport'),anchor=view.clientHeight*.47,lineY=view.offsetTop+anchor;byId('now-line').style.top=lineY+'px';byId('now-line').hidden=Math.abs(pan)>5;byId('journey-stream').style.transform=`translate(-50%,${anchor-positionAt(data,now)+pan}px)`;app.querySelector('[data-action=return-now]').hidden=Math.abs(pan)<5;
  for(const s of data.segments){const el=byId('segment-'+s.id);el.classList.toggle('active',s===current);el.classList.toggle('past',s.end<=raw&&!s.overflow);el.style.setProperty('--phase-progress',Math.max(0,Math.min(1,(raw-s.start)/s.duration)));}
  for(const a of data.activities)byId('overview-'+a.activity.id)?.classList.toggle('active',current?.activityId===a.activity.id);
  let rem=0,progress=0,label='Aktueller Auftrag',title='';
  if(current){rem=current.activityId?remaining(data,current.activityId,raw):current.end-raw;title=current.activity.title;const full=current.activity.duration||current.duration;progress=Math.max(0,Math.min(100,(1-rem/full)*100));if(current.overflow)label='Ausserhalb der Unterrichtszeit';}
  else if(raw<data.start){rem=data.start-raw;label='Unterricht beginnt in';title='Ein guter Start steht bevor.';}
  else{label='Für heute geschafft';title=data.overflow?'Offene Aufträge sind rot markiert.':'Alle geplanten Aufträge sind abgeschlossen.';progress=100;}
  byId('current-label').textContent=label;byId('countdown').innerHTML=rem>0?`${Math.ceil(rem)}<span>min</span>`:'✓';byId('countdown-title').textContent=title;byId('lesson-progress').style.width=progress+'%';
  const finished=raw>=Math.max(data.contentEnd,data.end)&&Math.abs(pan)<5;
  const slot=byId('finished-slot');if(finished&&!slot.firstChild)slot.innerHTML=`<div class="finished-message"><div class="eyebrow">Unterrichtsende</div><h2>Der heutige Weg ist geschafft.</h2><p>Du kannst den Ablauf weiter anschauen oder einen anderen Unterrichtstag öffnen.</p><div class="row" style="justify-content:center"><button data-action="${plan().isDemo?'demo-reset':'enable-preview'}">${plan().isDemo?'Demo neu starten':'Vorschau ansehen'}</button><button data-action="library">Zu den Plänen</button></div></div>`;else if(!finished)slot.replaceChildren();
}
async function fullscreen(){try{if(document.fullscreenElement)await document.exitFullscreen();else if(document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else toast('Nutze die Vollbildfunktion deines Browsers.');}catch{toast('Nutze die Vollbildfunktion deines Browsers.');}}
function changeDuration(id,delta){const target=screen==='editor'?draft:plan(),a=target.activities.find(a=>a.id===id);if(!a)return;a.duration=Math.max(1,Math.min(1440,a.duration+delta));target.updatedAt=Date.now();if(screen==='editor')renderEditorSchedule();else{persist();renderLesson();}}
function pickImage(callback){const input=document.createElement('input');input.type='file';input.accept='image/png,image/jpeg,image/webp,image/gif';input.addEventListener('change',async()=>{const file=input.files[0];if(!file)return;if(file.size>16000000){toast('Bitte ein Bild unter 16 MB auswählen.',true);return;}try{const value=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file);});if(!safeImage(value))throw new Error('Dieses Bildformat wird nicht unterstützt.');callback(value,file.name);}catch(e){toast(e.message||'Bild konnte nicht geladen werden.',true);}});input.click();}
function showSettings(){showDialog('Deine Ansicht',`<div class="setting-row"><div><label for="motion-toggle">Langsame Bewegung</label><p>Ausgeschaltet folgt der Ablauf in Minutenschritten.</p></div><input id="motion-toggle" type="checkbox" ${state.settings.motion?'checked':''}></div><div class="setting-row"><div><label for="background-opacity">Stärke des Hintergrunds</label><p>Weniger Farbe sorgt für mehr Ruhe.</p></div><input id="background-opacity" type="range" min="0" max="100" value="${Math.round(state.settings.backgroundOpacity*100)}"></div><p style="margin-top:18px">Hintergrund, Symbole und Aufträge kannst du unter «Bearbeiten» selbst ändern.</p>`,`<button class="primary" data-action="close-dialog">Fertig</button>`);byId('motion-toggle').addEventListener('change',e=>{state.settings.motion=e.target.checked;persist();updateLesson();});byId('background-opacity').addEventListener('input',e=>{state.settings.backgroundOpacity=Number(e.target.value)/100;app.querySelector('.lesson').style.setProperty('--bg-opacity',state.settings.backgroundOpacity);persist();});}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),15000);}
function portableHTML(){const doc=document.documentElement.cloneNode(true);doc.querySelector('#app').replaceChildren();doc.querySelectorAll('.toast').forEach(el=>el.remove());doc.querySelector('#embedded-data').textContent=JSON.stringify(state).replace(/</g,'\\u003c');doc.querySelector('#pwa-loader')?.remove();doc.querySelector('link[rel=manifest]')?.remove();doc.querySelector('link[rel=icon]')?.remove();doc.querySelector('meta[http-equiv="Content-Security-Policy"]')?.setAttribute('content',"default-src 'none'; img-src data: blob:; style-src 'unsafe-inline'; script-src 'unsafe-inline'; connect-src https://djufer1.github.io; font-src 'none'; base-uri 'none'; object-src 'none'");return '<!doctype html>\n'+doc.outerHTML;}
function exportDialog(){showDialog('Speichern & weitergeben',`<p>Die lokale Sicherung gehört zu diesem Browser. Eine Datei bewahrt deine Sammlung unabhängig davon auf.</p><button class="export-choice" data-action="export-html">${ico('download')}<span><strong>Fertige Browserdatei</strong><small>Programm, alle Unterrichtstage, Bilder und KI-Anweisungen in einer HTML-Datei. Direkt offline öffnen.</small></span></button><button class="export-choice" data-action="export-json">${ico('folder')}<span><strong>Sammlung sichern</strong><small>Pläne und Bilder als Datei. Auf einem anderen Gerät unter «Sammlung laden» öffnen.</small></span></button><button class="export-choice" data-action="export-ai">${ico('spark')}<span><strong>Dokumente für lokalen KI Agenten</strong><small>Lesbare Plandaten, einzelne Bilder und die Tagesablauf-Anweisungen als Ordner. In der lokalen KI öffnen; neue Bilder benötigen ein Bildwerkzeug.</small></span></button><button class="export-choice" data-action="ai-help">${ico('help')}<span><strong>KI-Anweisungen ansehen</strong><small>Die Kriterien für Tagesplanung, Symbole und Reisehintergründe lesen oder herunterladen.</small></span></button>`);}
function aiText(){return document.getElementById('ai-instructions').textContent.trim();}
function schemaText(){return document.getElementById('data-schema').textContent.trim();}
function importCollection(){const input=document.createElement('input');input.type='file';input.accept='.json,.html';input.addEventListener('change',async()=>{const f=input.files[0];if(!f)return;if(f.size>150000000){toast('Bitte eine Sammlung unter 150 MB auswählen.',true);return;}try{const text=await f.text();let raw;if(/^\s*</.test(text)){const doc=new DOMParser().parseFromString(text,'text/html');const embedded=doc.getElementById('embedded-data');if(!embedded)throw new Error('In dieser HTML-Datei wurde keine Sammlung gefunden.');raw=JSON.parse(embedded.textContent);}else raw=JSON.parse(text);const incoming=validateCollection(raw);showDialog('Sammlung laden',`<p><strong>${incoming.plans.length} ${incoming.plans.length===1?'Unterrichtstag':'Unterrichtstage'}</strong> ${incoming.plans.length===1?'wurde':'wurden'} gefunden. Möchtest du sie ergänzen oder deine aktuelle Sammlung ersetzen?</p><p>Beim Ergänzen werden Pläne mit derselben Kennung aktualisiert. Andere Pläne bleiben erhalten.</p>`,`<button data-action="close-dialog">Abbrechen</button><button id="import-replace">Ersetzen</button><button class="primary" id="import-merge">Ergänzen</button>`);byId('import-merge').addEventListener('click',()=>applyImport(incoming,false));byId('import-replace').addEventListener('click',()=>{if(confirm('Aktuelle Sammlung ersetzen? Sichere sie vorher als Datei, falls du sie behalten möchtest.'))applyImport(incoming,true);});}catch(e){toast('Laden fehlgeschlagen: '+e.message,true);}});input.click();}
function applyImport(incoming,replace){closeDialog();if(replace){const ownId=state.libraryId;state=incoming;state.libraryId=ownId;}else{const remap={};for(const [id,b]of Object.entries(incoming.assets.backgrounds)){let next=id;if(state.assets.backgrounds[id]&&state.assets.backgrounds[id].src!==b.src)next=id+'-'+uid().slice(0,8);state.assets.backgrounds[next]=b;remap[id]=next;}for(const p of incoming.plans){p.backgroundId=remap[p.backgroundId]||p.backgroundId;const idx=state.plans.findIndex(a=>a.id===p.id);if(idx>=0)state.plans[idx]=p;else state.plans.push(p);}if(!state.assets.atlas)state.assets.atlas=incoming.assets.atlas;if(!state.assets.fageAtlas)state.assets.fageAtlas=incoming.assets.fageAtlas;}persist();screen='library';groupValue='';search='';weekdayFilter='';render();toast('Deine Sammlung wurde geladen.');}
function help(){showDialog('Gut zu wissen',`<div class="help-copy"><h3>Vorbereiten</h3><p>Erstelle mehrere Tage und ordne sie nach Klasse, Wochentag und Themenblock. Über «Duplizieren» kannst du bewährte Abläufe wiederverwenden. Feste Pausen ergeben sich aus den Lücken zwischen Unterrichtszeiten.</p><h3>Im Unterricht</h3><p>Die Jetzt-Markierung steht fest. Die Aufträge bewegen sich daran vorbei nach oben. Mit dem Mausrad kannst du andere Abschnitte ansehen; «Zurück zu Jetzt» bringt dich zurück. Unter «Bearbeiten» kannst du Zeiten ändern. Die Folgeaufträge werden verschoben. Was nicht mehr hineinpasst, wird rot.</p><h3>Demo-Tag</h3><p>Der einzige Beispieltag nutzt eine eigene laufende Demo-Uhr. Er startet beim Öffnen fünf Minuten nach Unterrichtsbeginn, unabhängig von Datum und Gerätezeit. Du kannst pausieren, die Uhr einstellen, vor- und zurückspringen oder neu starten. Ein Duplikat wird zu einem regulären Unterrichtstag.</p><h3>Eigener Unterricht und Vorschau</h3><p>Deine selbst erstellten und duplizierten Tage starten mit der Systemzeit deines Geräts. Die Vorschau nutzt eine frei einstellbare Uhrzeit. «Echtzeit» folgt der Uhr dieses Geräts. Ein Datum ordnet deinen Plan zu; es startet ihn nicht automatisch. Öffne den passenden Unterrichtstag selbst.</p><h3>Lokal speichern</h3><p>Pläne und Bilder werden in diesem Browser auf diesem Gerät gesichert. Browserdaten können gelöscht werden. Sichere wichtige Sammlungen über «Speichern & teilen». Zwischen Geräten gibt es keinen automatischen Abgleich.</p><h3>Mit einer KI vorbereiten</h3><p>Nutze «KI-Agent verbinden» und öffne den bereitgestellten Ordner in deiner lokalen KI. Dort liegen die «Anweisungen KI-Agent» mit dem Skill «Class Journey». Es enthält die vollständigen Tagesablauf-Anweisungen und das Datenformat. Ein LLM braucht Dateiwerkzeuge und für neue Bilder zusätzlich eine Bildgenerierung.</p><h3>Auf Windows und Mac verwenden</h3><p>Unter «Updates → Für Windows & Mac herunterladen» erhältst du einen ZIP-Ordner von GitHub. Entpacke ihn, lege den Ordner an deinem gewünschten Ort ab und öffne ClassJourney.html im Browser. Er läuft vollständig lokal und offline. Sichere die eigenen Pläne vor einem Programmwechsel über «Speichern & teilen».</p><h3>Optional als Browser-App installieren</h3><p>Die Webversion kann in unterstützten Browsern auf Windows und Mac installiert werden. Nutze das Installationssymbol des Browsers, in Chrome/Edge «Seite als App installieren» oder auf einem unterstützten Mac «Zum Dock hinzufügen». Die lokale HTML-Datei braucht keine Installation.</p></div>`,`<button class="primary" data-action="close-dialog">Verstanden</button>`,650);}
function showDownloads(){showDialog('ClassJourney herunterladen',`<p>Wähle das Paket für deinen Computer. Die Browserdatei bleibt als zusätzliche Offline-Variante verfügbar.</p><button class="export-choice" data-action="download-windows">${ico('computer')}<span><strong>Windows-Installer</strong><small>Setup für Windows mit Startmenü-Eintrag. Installation im eigenen Benutzerkonto.</small></span></button><button class="export-choice" data-action="download-mac">${ico('computer')}<span><strong>Mac-Installer</strong><small>Eine DMG-Datei für Intel und Apple Silicon. ClassJourney nach «Programme» ziehen.</small></span></button><button class="export-choice" data-action="download-portable">${ico('folder')}<span><strong>Ordner für Windows & Mac</strong><small>ZIP entpacken und ClassJourney.html im Browser öffnen.</small></span></button><p class="section-note">Die Installer haben derzeit kein Herstellerzertifikat. Das Betriebssystem kann eine manuelle Freigabe verlangen. Beim ersten Wechsel von der Browserdatei zur installierten App die eigene Sammlung über «Speichern & teilen» übertragen.</p>`);}
function updateDialog(){const version=desktopInfo?.version||APP_INFO.version;if(desktop){showDialog('ClassJourney aktualisieren',`<p>Installierte App · Version <strong>${escape(version)}</strong></p><div id="update-result" class="notice">${nativeInstallerReady?'Der Installer wurde heruntergeladen und seine Prüfsumme bestätigt.':'Prüfe auf eine neuere Version im GitHub-Repository von DJufer1.'}</div>${nativeInstallerReady?'<button class="primary" data-action="open-native-installer">Installer öffnen</button>':''}<button class="export-choice" data-action="check-update">${ico('download')}<span><strong>Auf Updates prüfen</strong><small>Prüft die neueste veröffentlichte Version und den passenden Installer für dieses Gerät.</small></span></button><p>Deine Pläne und Bilder liegen im separaten lokalen Datenordner. Vor dem Öffnen des Update-Installers wird dort zusätzlich eine Sicherung erstellt.</p><p class="section-note">${desktopInfo?.platform==='darwin'?'Mac: Im geöffneten Installer die neue App nach «Programme» ziehen und die alte App ersetzen.':'Windows: Den geöffneten Setup-Assistenten ausführen.'} Für Updates ist eine Internetverbindung nötig; der Unterricht funktioniert offline.</p>`,`<button data-action="download-program">Alle Downloads</button><button class="primary" data-action="close-dialog">Schliessen</button>`);return;}
showDialog('ClassJourney aktualisieren',`<p>Browserdatei · Version <strong>${escape(version)}</strong></p><div id="update-result" class="notice">Programmversionen werden über das GitHub-Repository von DJufer1 bereitgestellt.</div><button class="export-choice" data-action="check-update">${ico('download')}<span><strong>Auf Updates prüfen</strong><small>Prüft auf eine neuere Browserdatei.</small></span></button><button class="export-choice" data-action="download-program">${ico('computer')}<span><strong>Installer für Windows & Mac</strong><small>Die App auf deinem Computer installieren oder den portablen Ordner laden.</small></span></button><button class="export-choice" data-action="publish-update">${ico('upload')}<span><strong>Update auf GitHub hochladen</strong><small>Für DJufer1: Öffnet das Programm-Repository. Persönliche Unterrichtspläne dort nicht hochladen.</small></span></button><p class="section-note">Sichere deine Sammlung vor einem Wechsel über «Speichern & teilen». Installierte App, Browserdatei und Webversion verwenden getrennte lokale Speicher.</p>`);}
async function checkUpdate(){const result=byId('update-result');if(!result)return;result.textContent='Version wird geprüft …';try{let version,available;if(desktop){const update=await desktop.checkUpdates();version=update.version;available=update.available;}else{const response=await fetch(APP_INFO.updateUrl,{cache:'no-store'});if(!response.ok)throw new Error();const remote=await response.json();version=remote.version;available=compareVersions(version,APP_INFO.version)>0;}result.replaceChildren();const message=document.createElement('span');message.textContent=available?'Version '+version+' ist verfügbar.':'Du verwendest die aktuelle Version.';result.append(message);if(available){const button=document.createElement('button');button.className='small primary';button.dataset.action=desktop?'download-native-update':'download-update';button.textContent=desktop?'Update herunterladen':'Neue Browserdatei laden';result.append(button);}}catch(error){result.textContent=desktop?error.message:'Die Prüfung ist gerade nicht möglich. Prüfe deine Internetverbindung.';}}
async function downloadUpdate(){try{const response=await fetch(APP_INFO.downloadUrl,{cache:'no-store'});if(!response.ok)throw new Error();const text=await response.text();if(!text.includes('id="embedded-data"')||!text.includes('id="app-info"'))throw new Error();download('ClassJourney.html',text,'text/html;charset=utf-8');toast('Die neue Browserdatei wird heruntergeladen. Sichere deine Sammlung vor dem Wechsel.');}catch{toast('Der Download ist gerade nicht möglich.',true);}}
async function downloadNativeUpdate(){if(!desktop)return;const result=byId('update-result');nativeInstallerReady=null;if(result)result.textContent='Installer wird geladen …';try{await desktop.saveCollection(clone(state));const update=await desktop.downloadUpdate();if(!update.downloaded){if(result)result.textContent='Du verwendest die aktuelle Version.';return;}nativeInstallerReady=update;if(result){result.replaceChildren();const text=document.createElement('span');text.textContent='Version '+update.version+' wurde geladen. Die Prüfsumme ist bestätigt.';const button=document.createElement('button');button.className='small primary';button.dataset.action='open-native-installer';button.textContent='Installer öffnen';result.append(text,button);}else toast('Update geladen. Unter «Updates» den Installer öffnen.');}catch(error){if(result)result.textContent=error.message;else toast(error.message,true);}}
async function openNativeInstaller(){try{await desktop.saveCollection(clone(state));await desktop.openInstaller();}catch(error){toast(error.message,true);}}
async function handleAction(action,el){
  const id=el.dataset.id,value=el.dataset.value,delta=Number(el.dataset.delta);
  switch(action){
    case'group-mode':groupMode=value;groupValue='';renderLibrary();break;
    case'group':groupValue=value;renderLibrary();break;
    case'new':createDraft();break;
    case'edit-plan':createDraft(id);break;
    case'open':openLesson(id);break;
    case'preview':openLesson(id,true);break;
    case'library':screen='library';render();break;
    case'cancel-editor':if(confirm('Bearbeitung verwerfen und zu den Plänen zurückkehren?')){screen='library';render();}break;
    case'save-plan':savePlan();break;
    case'duplicate':{const p=clone(state.plans.find(p=>p.id===id));p.id=uid();p.title+=' · Kopie';p.date='';p.example=false;p.isDemo=false;p.activities.forEach(a=>a.id=uid());p.updatedAt=Date.now();state.plans.push(p);persist();renderLibrary();toast('Plan dupliziert. Datum und Zeiten kannst du anpassen.');break;}
    case'delete-plan':if(confirm('Diesen Unterrichtstag löschen?')){state.plans=state.plans.filter(p=>p.id!==id);persist();renderLibrary();}break;
    case'toggle-lesson':{const lesson=DEFAULT_LESSONS.find(l=>l.number===Number(value));if(!lesson)break;const index=draft.slots.findIndex(s=>s.start===lesson.start&&s.end===lesson.end);if(index>=0){if(draft.slots.length===1){toast('Mindestens eine Unterrichtslektion muss ausgewählt bleiben.');break;}draft.slots.splice(index,1);}else draft.slots.push({start:lesson.start,end:lesson.end});draft.slots.sort((a,b)=>a.start.localeCompare(b.start));renderEditor();break;}
    case'add-slot':{let end=0;try{end=minutes(draft.slots.at(-1).end);}catch{}const next=DEFAULT_LESSONS.find(l=>minutes(l.start)>=end&&!draft.slots.some(s=>s.start===l.start&&s.end===l.end));if(next)draft.slots.push({start:next.start,end:next.end});else{if(end+50>=1440){toast('Die zusätzliche Lektion passt nicht mehr in diesen Tag.',true);break;}draft.slots.push({start:timeLabel(end+5),end:timeLabel(end+50)});}renderEditor();break;}
    case'remove-slot':draft.slots.splice(Number(el.dataset.index),1);renderEditor();break;
    case'choose-bg':draft.backgroundId=id;renderEditor();break;
    case'upload-bg':pickImage((src,name)=>{const id='custom-'+uid();state.assets.backgrounds[id]={name:name.replace(/\.[^.]+$/,''),src,prompt:''};draft.backgroundId=id;persist();renderEditor();});break;
    case'add-activity':openActivity();break;
    case'edit-activity':openActivity(id);break;
    case'save-activity':saveActivity();break;
    case'duration':changeDuration(id,delta);break;
    case'delete-activity':if(confirm('Diesen Auftrag löschen?')){draft.activities=draft.activities.filter(a=>a.id!==id);renderEditorSchedule();}break;
    case'move-activity':{const from=draft.activities.findIndex(a=>a.id===id),to=from+delta;if(to>=0&&to<draft.activities.length)[draft.activities[from],draft.activities[to]]=[draft.activities[to],draft.activities[from]];renderEditorSchedule();break;}
    case'choose-icon':editingActivity.icon=value;editingActivity.image='';activeDialog.querySelectorAll('.symbol-option').forEach(b=>b.classList.toggle('selected',b.dataset.value===value));byId('custom-icon-preview').replaceChildren();break;
    case'upload-icon':pickImage(src=>{editingActivity.image=src;byId('custom-icon-preview').innerHTML=art(editingActivity);activeDialog.querySelectorAll('.symbol-option').forEach(b=>b.classList.remove('selected'));});break;
    case'close-dialog':closeDialog();break;
    case'lesson-edit':showDialog('Ablauf anpassen',`<p>Ändere eine Dauer. Die nachfolgenden Aufträge verschieben sich entsprechend.</p><div class="activity-list">${lessonData.activities.map(a=>`<div class="activity-row ${a.overflow?'overflow':''}">${art(a.activity)}<div><h3><span class="editable-title" contenteditable="plaintext-only" role="textbox" data-title="${a.activity.id}" aria-label="Titel ${escape(a.activity.title)}">${escape(a.activity.title)}</span></h3><small>${timeLabel(a.start)}–${timeLabel(a.end)}${a.overflow?' · '+a.overflow+' min ausserhalb':''}</small></div><button class="small" data-action="edit-activity" data-id="${a.activity.id}">${ico('edit')}Anpassen</button></div>`).join('')}</div>`,`<button data-action="edit-selected">Ganzen Plan bearbeiten</button><button class="primary" data-action="close-dialog">Fertig</button>`,700);break;
    case'edit-selected':closeDialog();createDraft(selectedId);break;
    case'fullscreen':fullscreen();break;
    case'settings':showSettings();break;
    case'return-now':pan=0;updateLesson();break;
    case'pan-activity':{const a=lessonData.activities.find(a=>a.activity.id===id);pan=positionAt(lessonData,nowMinutes())-(a.segments[0].y+a.segments[0].height/2);updateLesson();break;}
    case'enable-preview':lessonClock.open(plan(),true);pan=0;renderLesson();break;
    case'live':lessonClock.open(plan());pan=0;renderLesson();break;
    case'demo-toggle':lessonClock.toggle();renderLesson();break;
    case'demo-reset':lessonClock.reset();pan=0;renderLesson();break;
    case'preview-step':lessonClock.step(delta);pan=0;byId('preview-time').value=timeLabel(nowMinutes()).slice(0,5);updateLesson();break;
    case'import':importCollection();break;
    case'export':if(screen==='editor')toast('Speichere zuerst den bearbeiteten Unterrichtstag.');else exportDialog();break;
    case'export-html':download('ClassJourney.html',portableHTML(),'text/html;charset=utf-8');toast('Deine fertige Browserdatei wird heruntergeladen.');break;
    case'export-json':download('Sammlung.classroomscreen.json',JSON.stringify(state),'application/json');break;
    case'export-ai':await exportWorkspace();break;
    case'connect-agent':if(screen==='editor')toast('Speichere zuerst den bearbeiteten Unterrichtstag.');else connectAgent();break;
    case'agent-help':agentHelp();break;
    case'agent-folder':await provideAgentFolder();break;
    case'copy-agent-prompt':await copyAgentPrompt();break;
    case'agent-import':closeDialog();importCollection();break;
    case'ai-help':showDialog('Anweisungen KI-Agent',`<p>Diese Anweisungen sind in jeder Browserdatei und im KI-Paket enthalten.</p><textarea class="ai-text" id="ai-text-view" readonly aria-label="Tagesablauf-Skill"></textarea>`,`<button data-action="download-skill">Anweisungen herunterladen</button><button class="primary" data-action="close-dialog">Schliessen</button>`,760);byId('ai-text-view').value=aiText();break;
    case'download-skill':download('CLASS-JOURNEY-SKILL.md',aiText(),'text/markdown;charset=utf-8');break;
    case'help':help();break;
    case'updates':updateDialog();break;
    case'check-update':await checkUpdate();break;
    case'download-update':await downloadUpdate();break;
    case'download-program':showDownloads();break;
    case'download-windows':window.open(APP_INFO.windowsInstallerUrl,'_blank','noopener,noreferrer');break;
    case'download-mac':window.open(APP_INFO.macInstallerUrl,'_blank','noopener,noreferrer');break;
    case'download-portable':window.open(APP_INFO.portableUrl,'_blank','noopener,noreferrer');break;
    case'download-native-update':await downloadNativeUpdate();break;
    case'open-native-installer':await openNativeInstaller();break;
    case'open-web':window.open(APP_INFO.url,'_blank','noopener,noreferrer');break;
    case'publish-update':window.open(APP_INFO.uploadUrl,'_blank','noopener,noreferrer');break;
    case'install':if(installPrompt){installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;document.querySelectorAll('[data-action=install]').forEach(b=>b.hidden=true);}else help();break;
  }
}
app.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(el&&!el.disabled){event.preventDefault();Promise.resolve(handleAction(el.dataset.action,el)).catch(e=>toast(e.message||'Die Aktion konnte nicht ausgeführt werden.',true));}});
new MutationObserver(()=>app.querySelectorAll('button').forEach(button=>{if(!button.title)button.title=button.getAttribute('aria-label')||button.querySelector('strong')?.textContent.trim()||button.textContent.trim().slice(0,90);})).observe(app,{childList:true,subtree:true});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&screen==='lesson'&&!activeDialog){pan=0;updateLesson();}if(e.key.toLowerCase()==='f'&&screen==='lesson'&&!activeDialog&&!/input|textarea|select/i.test(e.target.tagName)){e.preventDefault();fullscreen();}});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;document.querySelectorAll('[data-action=install]').forEach(b=>b.hidden=false);});
window.addEventListener('resize',()=>{if(screen==='lesson')updateLesson();});
if(matchMedia('(prefers-reduced-motion:reduce)').matches)state.settings.motion=false;
if(desktop)desktop.onUpdateProgress(percent=>{const result=byId('update-result');if(result)result.textContent='Installer wird geladen … '+percent+' %';});
openStorage();render();
// WORKSPACE_FUNCTIONS
})();
